14	use TestDriver_Area_WizardTest_Wizard_Step_Countries;
15	
16	final class WizardTest extends ApplicationTestCase
17	{
18	    protected TestDriver_Area_WizardTest_Wizard $wizard;
19	
20	    private const WIZARD_BASE_URL = 'https://example.com/admin/?page=wizardtest&mode=wizard';
21	
22	    public function setUp() : void
23	    {
24	        parent::setUp();
25	        $this->startTransaction();
26	
27	        $this->cleanUpTables(array(Application_Countries::TABLE_NAME));
28	
29	        $driver = Application_Driver::getInstance();
30	        $screen = $driver->getScreenByPath('wizardtest.wizard');
31	
32	        $this->assertNotNull($screen, 'Screen could not be found by path.');
33	        $this->assertInstanceOf(TestDriver_Area_WizardTest_Wizard::class, $screen);
34	
35	        $this->wizard = $screen;
36	
37	        // The wizard screen is a singleton cached by the driver's subscreen
38	        // registry. Reset its internal state so each test starts with an empty
39	        // steps array and clean session state.
40	        $this->wizard->resetForTest();
41	    }
42	
43	    public function tearDown() : void
44	    {
45	        unset($_REQUEST['wizard']);
46	        parent::tearDown();
47	    }
48	
49	    // -------------------------------------------------------------------------
50	    // test_wizardSteps
51	    // -------------------------------------------------------------------------
52	
53	    public function test_wizardSteps() : void
54	    {
55	        $this->wizard->handleActions();
56	        $countriesStep = $this->wizard->getStep('Countries');
57	
58	        $ticketStep = $this->wizard->getStep('Ticket');
59	        $ticketStep->process();
60	        $this->assertTrue($ticketStep->isComplete());
61	
62	        $summaryStep = $this->wizard->getStep('Summary');
63	        $summaryStep->process();
64	        $this->assertTrue($summaryStep->isComplete());
65	
66	        $this->wizard->changeCountry(CountryGB::ISO_CODE);
67	        $countriesStep->process();
68	        $this->assertFalse($ticketStep->isComplete());
69	        $this->assertFalse($summaryStep->isComplete());
70	    }
71	
72	    // -------------------------------------------------------------------------
