74	    // -------------------------------------------------------------------------
75	
76	    /**
77	     * Verifies that when a WizardConfigurator preselection session is injected,
78	     * the Countries step data is initialised with the preselected country_id
79	     * (merged over its null default) by the WP-002 constructor merge fix.
80	     *
81	     * Pattern: create countries manually → build preselection session → inject
82	     * session ID → initWizard + initSteps → assert step data before any process().
83	     */
84	    public function test_preselectedValuesAppliedToStep() : void
85	    {
86	        // Ensure the required countries exist in the DB before building the
87	        // preselection so we have a real country ID to reference.
88	        $countries = AppFactory::createCountries();
89	        foreach (array(
