154	            if (!$countries->isoExists($iso)) {
155	                $countries->createNewCountry($iso, $label);
156	            }
157	        }
158	
159	        $gbId = $countries->getByISO(CountryGB::ISO_CODE)->getID();
160	        $deId = $countries->getByISO(CountryDE::ISO_CODE)->getID();
161	
162	        // Build a preselection session with GB country.
163	        $configurator = new WizardConfigurator(self::WIZARD_BASE_URL);
164	        $configurator->getPreselection()->setStepValue(
165	            'Countries',
166	            TestDriver_Area_WizardTest_Wizard_Step_Countries::VALUE_COUNTRY_ID,
167	            $gbId
168	        );
169	
170	        $url = $configurator->getRedirectURL();
171	        parse_str((string)parse_url($url, PHP_URL_QUERY), $params);
172	        $sessionId = (string)($params['wizard'] ?? '');
173	
174	        $this->assertNotEmpty($sessionId, 'Preselection session ID must not be empty.');
