201	        $this->assertSame(
202	            $deId,
203	            $sessionAfter['-step_Countries'][TestDriver_Area_WizardTest_Wizard_Step_Countries::VALUE_COUNTRY_ID],
204	            'After step save the Countries step slot must contain the processed DE country_id.'
205	        );
206	
207	        $this->assertTrue(
208	            $sessionAfter['-step_Countries']['completed'] ?? false,
