129	    * Called before rendering the step's contents. Must return
130	    * a boolean value indicating whether the step has been
131	    * completed, in which case the wizard can jump to the next step.
132	    *
133	    * @return boolean
134	    */
135	    public function process() : bool
136	    {
137	        $this->log('Process | Pre-Process');
138	
139	        $this->preProcess();
140	
141	        $result = $this->_process();
142	
143	        $this->log(sprintf('Process | Processed: [%s].', parseVariable($result)));
144	
145	        // processing was successful
146	        if($result)
147	        {
148	            // The step has not been completed before:
149	            // we set it to complete.
150	            if(!$this->isComplete()) {
151	                $this->setComplete();
152	            }
153	            // the step has been completed before, and
154	            // some data has changed: we need to
155	            // let the other steps adjust to the changes.
156	            else if($this->updateRequired)
157	            {
158	                $this->wizard->handle_stepUpdated($this);
159	            }
160	        }
161	
162	        return $result;
163	    }
