115	    /**
116	     * Creates a new wizard session, initialises the invalidation handler key,
117	     * and writes all preselection values into the session step data slots using
118	     * the key format the wizard trait already reads:
119	     * `settingPrefix + '-step_' + stepName`.
120	     *
121	     * @return string The newly created session ID.
122	     */
123	    private function createSession() : string
124	    {
125	        $sessionID = BaseWizardMode::generateNewSessionID();
126	
127	        $session = AppFactory::createSession();
128	        $data = $session->getValue($sessionID);
129	
130	        $invalidationHandler = new InvalidationHandler();
131	        $invalidationHandler->setIsInvalidated(false);
132	
133	        $data[$this->settingPrefix . '-invalidationHandler'] = $invalidationHandler;
134	
135	        foreach ($this->preselection->getStepNames() as $stepName)
136	        {
137	            $key = $this->settingPrefix . '-step_' . $stepName;
138	            $data[$key] = $this->preselection->getStepValues($stepName);
139	        }
140	
141	        $session->setValue($sessionID, $data);
142	
143	        return $sessionID;
144	    }
145	}

