107	    public function initWizard() : void
108	    {
109	        $this->wizardID = $this->getWizardID();
110	        $this->classBase = $this->getClassBase();
111	
112	        // create or get the wizard session ID: this is used to
113	        // identify a specific wizard session, and enables the
114	        // same user to use several parallel wizards. The ID is
115	        // included in all URLs and forms.
116	        $this->sessionID = $this->request->getParam('wizard');
117	
118	        if (empty($this->sessionID))
119	        {
120	            $this->createSession();
121	
122	            if(!BaseConfigRegistry::areUnitTestsRunning()) {
123	                $this->redirectTo($this->getURL($this->request->getRefreshParams()));
124	            }
125	        }
126	
127	        $data = $this->session->getValue($this->sessionID);
128	
129	        if(empty($data))
130	        {
131	            $this->createSession();
132	
133	            if(!BaseConfigRegistry::areUnitTestsRunning()) {
134	                $this->redirectTo($this->getURL($this->request->getRefreshParams()));
135	            }
136	        }
137	
138	        $this->log('Using existing wizard ID [%s].', $this->getWizardID());
139	
140	        $this->sessionData = $this->session->getValue($this->sessionID);
141	        $this->invalidationHandler = $this->getWizardSetting('invalidationHandler');
142	
143	        if ($this->sessionData['userID'] !== $this->user->getID())
144	        {
145	            $this->redirectWithInfoMessage(
146	                UI::icon()->information() . ' ' .
147	                t('Wizards can not be shared between users.'),
148	                $this->getCanceledURL()
149	            );
150	        }
151	    }
