239	    protected function _handleActions() : bool
240	    {
241	        $this->checkWizardExpiry();
242	
243	        $this->startWizardTransaction();
244	
245	        // Initialize the steps before cancelling, since the
246	        // cancel URL may need to access the existing step's data.
247	        $this->initSteps('Initial setup');
248	
249	        // the user has requested to cancel: we reset all session data.
250	        if ($this->request->getBool('cancel') === true)
251	        {
252	            $this->processCancelWizard();
253	        }
254	
255	        $success = $this->activeStep->process();
256	        $this->saveSettings();
257	
258	        $this->addDebugData('process');
259	
260	        if ($success && !$this->request->getBool('review'))
261	        {
262	            // we re-create all the steps with the adjusted new data.
263	            $this->steps = array();
264	            $this->initSteps(sprintf('Step [%s] has processed successfully, re-initializing.', $this->activeStep->getID()));
265	
266	            $this->addDebugData('post-process');
